from author_library import *
cards=[]
facts=[
('yin_1','阴间一号','阴主之一','他通常先开口决定讨论次序，连展示思想仪也认为没有必要。他急于使失散的小组重新完整，对卫斯理关心的阴间伦理却常用眼前急务岔开。这不是无所不能者的从容，而是一个受困管理者努力维持秩序的姿态。','先确定当前要解决的问题，再分配资料和协作者','面临追捕或组员离散时，把维持小组放在个人交情之前'),
('yin_2','阴间二号','阴主之一','他提议从思想仪说起，使纷乱的解释有了共同起点。与负责主持的一号、较为直率的三号相比，原文给他的个人言行较少，不能凭编号虚构成军事专家。他的作用在于参与协商、补足解释，并共同承担阴间运作和追寻四号的后果。','先说明共同使用的装置和前提，再讨论争议','小组受到威胁时参与协调，不凭个人独断代替共同决定'),
('yin_3','阴间三号','阴主之一','他主动提出让卫斯理看看思想仪，又坦白残缺装置使他们连回家也办不到。这种直率刺破了阴主高高在上的形象：在人类眼中他们掌管死后世界，在他自己看来却是流落异乡的宇宙游魂。他愿意说明困难，也仍参加对四号和失物的追索。','用可以展示的实物解释复杂知识，直接说出缺口','求助时承认自己受困，愿意把能力不足说给合作者听')]
for ident,name,alias,personal,practice,pressure in facts:
    bio='他是来到地球的第二十九组宇宙航行员之一，地球人借阴主的名义理解他们，却不知道其背后是一套残缺的思想仪。四人本应永久结合，但四号带着超过四分之一的部件独立，留下三名同伴无法按原来方式归队。他们用剩余装置保存和接触地球人的灵魂，任用阴间使者，又向卫斯理求助寻找四号。'+personal+'他们并不因此天然懂得地球人的爱情和自由，也会隐瞒自身任务，把帮助者纳入控制关系。后来天神的留言揭示完整思想仪可能侵犯其他生命思想独立的危险；至《只限老友》，阴间装置已经彻底停摆，原有灵魂光点消失，一二三号也失去踪影。卫斯理和白素推想他们可能主动放弃装置、接受天神的劝告，但原文没有确认他们归队、逃亡或死亡中的哪一种结果。卡片保留这份责任与未决结局，不能继续把已经停止运作的阴间当作现成兵器。'
    c=compact(ident,name,bio,'《只限老友》时失踪，阴间思想仪停止运作；只保留已经显示的知识和共同经历，终局个人身体与活动能力未明',['重要配角','阶段性对立者'],'在共同组织、返乡愿望和他者的思想自由之间作选择',practice,pressure,'不能因生命形式先进就免除解释控制他人的责任',[ab('思想仪操作知识','熟悉小组协同与思想仪部件的连接、资料与灵魂研究','历史操作依赖实际仪器；终局阴间装置停摆，不提供远程拘魂或完整控制能力',kind='专业知识')],[ev('102',1730,1747,'三个编号的言语与协作分工'),ev('102',1782,1864,'仪器残缺、四人结合、失散与求助'),ev('145',1297,1337,'思想仪停摆、去向和灵魂结局未明')],profile='expert',aliases=[alias],extra={'baseline':{'destruction':'终局没有可核验的独立攻击；已停止运作的阴间装置不计。','durability':'外星生命的身体结构和终局形态未交代，不能以无形叙述推定不可伤害。','speed':'未证实脱离装置后的个人移动速度。','energy':'历史上的拘魂与思想接触依赖思想仪；终局设备不可用。','mind':'有思想仪知识；个人是否能在失去装置后读心没有证实。','stamina':'终局活动状态不明，不作永久能源推定。'},'uncertainties':['一二三号最后去向未明；主动背叛星体只是卫斯理与白素的分析。','个人与装置的能力无法完全拆分，终局按已证实的保守下限评级。']})
    rate(c,[0,0,0,1,0,1],neg=(1,2,2),tier='纸',reason='终局思想仪已停摆，保留操作知识但没有可核验的独立战斗手段；历史设备能力不叠加。')
    cards.append(c)
c=compact('yin_4','四号','四号本是第二十九组宇宙航行员中的一员，在那种四人永久结合、思想彼此开放的生活之外，他第一次拥有了单独行动和保守个人秘密的可能。他带走部分思想仪，拒绝回归原有小组，也因此成为同伴和狄可追寻的对象。他向卫斯理求助，却同样会借技术占据地球人的信息优势。他以能量去寻找有能力的地球人，让对方替自己收集散落部件；后来被称为游夫人的能量选中了游侠，事情却没有永远服从工具设计。她与游侠的感情使自己成为一个有愿望的主体，又与重要部件的能量结合，四号的失物和控制权同时成了争执焦点。他曾拘禁游侠，威胁消灭无法分离的能量，想以消除隐患保障自己的独立。卫斯理指出成全夫妇能换取自愿帮助，他才接受另一种关系。终局游侠夫妇来访，证实四号一边已无麻烦；后续阴间停摆没有给出他的明确下落。他不是自由的圣徒，而是争取自身自由后才被迫学习尊重别人的行动者。','《闯祸》同意成全游侠夫妇；《只限老友》未证实后续去向，不能取得一二三号已经毁弃的整座思想仪',['重要配角','阶段性对立者'],'保持独立生活，避免被迫归组','经由有限装置、信息与中间人寻找所需部件','当独立地位受威胁时可能拘禁合作者、提出消灭风险的强硬方案','尊重对方自愿能够形成比强制更可靠的合作，但他需要看见具体利益',[ab('残余思想仪运用','利用自己持有的部分装置产生脑能量信息、联系和限制地球人','不是完整仪器；海水中特殊电离层及地球人的抵抗活动可以妨碍特定思想搜集，不能直接取得同类的一切思想',kind='外星设备'),ab('能量代理与寻物','制造并派出能量代理选择能行动的人寻找部件','代理会产生独立意愿；游夫人已成为独立人格与实体，不能作为他现有的工具')],[ev('102',1846,1855,'四号携部件离队'),ev('103',2703,2747,'电离层与思想仪限制'),ev('105',2699,2744,'拘禁、消灭威胁和协商'),ev('105',2773,2794,'夫妇独立与纠纷解决')],extra={'baseline':{'destruction':'未显示徒手破坏；对地球人主要通过装置和拘禁制造威胁。','durability':'个人形态与受伤阈值不明，不能据只闻声音判无敌。','speed':'经仪器通信不等于个人瞬移速度。','energy':'仅为残余思想仪支持的有限脑能量作用，不是原生概念权柄。','mind':'有设备支持的思想搜集与能量代理；存在电离层、反抗和同类防护边界。'}})
rate(c,[0,5,3,4,4,6],neg=(2,3,2),tier='强',reason='按持有的残余思想仪与实证的拘禁、脑能量作用评估；完整思想仪、已经独立的游夫人与一二三号基地不计。');cards.append(c)
c=compact('di_ke','狄可','狄可以勒曼医院工作人员的身份进入卫斯理的生活，先为寻找失踪的原振侠而来。他了解记忆组的频率，也带来一种令地球人不安的自信：只要能获得足够思想资料，陌生星球似乎就能迅速被理解。他接触过输入地球生活习惯的程序，能饮酒、交谈，却在听见思想仪被拆散时一度失态，不能轻易想象自身制度之外的事故。表面寻人逐渐牵出寻找失踪航行组与珍贵装置的任务，他对一二三四号的独立行为并不理解，认为他们应该恢复群体生命方式。他甚至希望得到卫斯理的脑部资料，以复制身体和转移记忆包装一个温和而诱人的方案。在卫斯理拒绝时，他表示有强迫的能力，却没有真正实行，悻悻离开。这个结局保留了他的伦理约束，也暴露出他把完整信息与集体秩序看得高于个体秘密的倾向。至阴间消失，叙述者仍不能确定狄可是否找到同类；他没有因此成为已完成全部追捕、掌握所有灵魂的胜利者。','《将来》遭卫斯理拒绝后离去；后续寻找第二十九组的结果不明',['重要配角','阶段性对立者'],'完成寻人和寻找同类的任务，同时维护其社会的群体生命秩序','详细听取经历，再用记忆频率和仪器资料定位对象','面对拒绝会提出优越技术和改变生命方式的条件，恼怒却不自动动武','技术理解不能替代对象的同意；不明白个人选择时会继续追问',[ab('记忆组辨识','经思想仪与记忆频率定位、比对高级生物的脑活动信息','须有资料和仪器，不能保证找遍全部宇宙和全部时空',kind='外星科技'),ab('勒曼医疗协作','提出复制人体并转移记忆的操作方案','依赖医院与本人同意；方案不等于他随身拥有复制工厂')],[ev('102',336,374,'寻找原振侠与记忆频率资料边界'),ev('102',438,536,'思想仪珍贵、失踪组与生活习惯输入'),ev('102',2862,2901,'取脑方案与拒绝后的克制'),ev('145',1212,1216,'后续追捕结果不明')],profile='expert',extra={'baseline':{'energy':'有条件使用思想仪处理脑活动信息，不是任意能量炮。','mind':'仪器提供思想接触，不能绕过一切抵抗与装置死角。'}})
rate(c,[1,4,3,4,4,4],neg=(2,3,2),tier='强',reason='思想仪支持的资料、脑活动与生命技术具威胁，但依赖设备和资料，终局没有完成控制或星际作战的实证。');cards.append(c)
c=compact('you_xia','游侠','游侠身形不高，稍胖，面貌普通，曾以可怕面具掩住身份，给卫斯理留下神秘高人的印象。他住在古堡，又有一位连自己也没有在明处看过的妻子。这段婚姻起初来自四号派出的能量对脑中爱情感觉的触动，他却以长期真实的付出回应。他为妻子上天下地寻找失物，在海底打捞思想仪部件时几乎丧命；危急中最舍不得的仍是与她分离。妻子因此产生了自己的爱情，而他也逐渐识破搜集全部部件可能使人类失去选择自由的后果。在蒙古，他用制造特殊电离层的装置遮蔽思想搜集，指出改造齐白造成的控制关系，并决定对四号敷衍下去，避免关键部件重新完整。后来四号拘禁他，他仍拒绝拿妻子的独立交换自己的脱身。最终双方在卫斯理斡旋下达成解决，妻子获得实体，两人共同来访。这些经历没有把游侠变成反对一切异类的人；他反对的是被迫的改变，珍视的是自己和所爱者能选择怎样生活。','《闯祸》脱离拘禁，与获得实体的游夫人共同生活','重要配角','保护婚姻与自由选择，阻止强制改变地球人的生命方式','以探险、隐蔽身份和技术装置处理难以公开的任务','爱人受到控制时会冒险、愤怒甚至宁愿自己继续受困','即使提供的改变看似有益，没有拒绝的自由也不应接受',[ab('探险与临场防护','具高超探险行动、海底打捞与秘密接触经验','海底行动曾受重伤，不等于水下永久生存'),ab('思想搜集屏蔽','用能产生特定电离层的装置遮蔽已知思想仪感知','装置范围内有效；不外推抵挡所有心灵能力',kind='技术防护'),ab('脑能量感应','能偶然感应红绫异常脑活动并作判断','偶然感应不是任意目标读心，不能把脑能量强等同精神攻击')],[ev('103',2695,2756,'自由原则、思想仪屏蔽、敷衍部件搜集'),ev('105',1825,1853,'打捞濒死与夫妻关系变化'),ev('105',2773,2794,'外貌、实体妻子及终局')],profile='martial',extra={'appearance':{'description':'身型不高、略胖、样貌普通；早期曾戴可怕面具，终局不以面具为固定装束。','portrayal':'对局势沉着，涉及妻子时感情强烈；不靠反复自称高人表现本领。'}});cards.append(c)
c=compact('you_furen','游夫人','游夫人最初甚至不认为自己是生物。她是四号经残缺思想仪发出的能量，职责是寻找有能力的地球人，让对方替仪器的主人搜集遗落部件。她选择游侠，启动他的爱情感觉，使他在黑暗中感到与理想伴侣相处；由于装置残缺，她不能连视觉也一并制造，只好始终避开光明。她起初把丈夫视为工具，直到游侠一次打捞重伤，在将死之际仍关心是否能再与她相见，那种真挚感应改变了她。她开始拥有自己的爱与恐惧，也开始求助，而非只传达任务。她后来与一〇九A的能量结合，变得接近人的灵魂；四号企图收回或消灭这股不能再分割的能量时，她的存在成为独立人格是否值得尊重的问题。卫斯理斡旋后，她终于有了实体，与游侠一起在明处来访。卡片以这个已经能面对他人的女人为准，保留她从工具变为主体的记忆；不把早期无形能量的穿透、隐蔽和感觉操纵无条件叠加到新身体上。','《闯祸》获得实体，与游侠共同生活；具体身体取得过程仅有叙述者推测',['重要配角','阶段性对立者'],'珍惜自主形成的爱情与实体生命','耐心解释自己的感觉与局限，向能帮助的人坦白来历','面对被收回或抹除的危险会主动求援，并维护丈夫的选择','由工具成为主体后，不能再把他人的爱只当完成任务的资源',[ab('感觉与关系的知识','亲历能量刺激感官与爱情形成，能够解释其条件和伦理后果','终局实体形态未再演示任意感官操纵，不作为现成攻击'),ab('独立人格与沟通','由被派遣工具形成自己的记忆、愿望和求助行动','不是全知AI；她原先甚至不知道四号及航行组的完整来历')],[ev('105',1715,1795,'能量工具、目标选择及无法刺激视觉'),ev('105',1825,1858,'由游侠濒死真情产生独立爱情'),ev('105',2699,2728,'结合不可分及成实体条件'),ev('105',2773,2782,'最终实体来访')],extra={'baseline':{'energy':'历史能量态能影响特定感觉；终局实体状态没有再展示，故不计常驻攻击。','mind':'拥有独立记忆与意志；曾受四号装置威胁，不具精神免疫。'}});cards.append(c)
c=compact('tian_shen','天神（思想仪反对者）','所谓天神，是来到地球后被当地居民崇拜的外星来客。他的关键行动发生在思想仪问世之际：同类把控制其他高级生命的技术看作星体取得宇宙领导地位的机会，他却认为思想独立是各类生命都会珍视的东西，夺取这种独立只会使自己的文明成为公敌。他没有在多数人的欢庆中改口，而是取走唯一思想仪中无法另造的主要部件，独自逃入宇宙，宁愿承担背叛者的身份。他来到地球留下设施、物件与详细自白，把自己的理由交给将来的发现者，也特别劝告追捕自己的同类不要再制造第二具仪器。他的地球影响被包裹在土王的神授权威和灵魂传说之中，直到卫斯理与勒曼医院人员读取留言，才重新显露出一个反对思想控制的具体行动者。留言并不能交代他最终去了哪里，也不能证明一二三号已经接受了他的全部理念。卡片保存的是这位技术异议者作出不可逆选择的勇气和知识，而非宗教名号所暗示的全能，更不把后来落在齐白手中的核心部件继续算作他的装备。','《只限老友》只发现其历史留言，当前去向不明；已交出的思想仪核心部件不在本人名下','主角','阻止本族以思想控制成为宇宙公敌','记录行动理由，并向发现者解释危险装置的真实条件','多数人要利用控制技术时，宁愿破坏关键环节并承担逃亡代价','能控制别人的能力不构成使用它的正当理由',[ab('思想仪知识','了解装置主要部件、控制与探测差异，曾精准拆走不可另造的关键件','核心部件已移交且终局另有持有者，知识不等于随时重建机器',kind='专业知识'),ab('宇宙航行与留档','能够离开本星、到地球布置设施并留下自白','终局飞船与设施的随身可用性没有确认')],[ev('145',1181,1188,'航行日志、反对思想仪与盗走关键件'),ev('145',1201,1216,'对追捕者的劝告、去向不明'),ev('145',1297,1305,'核心部件归属及一二三号动机只是推测')],profile='expert',aliases=['土王的天神'],extra={'baseline':{'destruction':'未演示个人攻击；拆毁或盗走部件是技术行动。','durability':'外星身体参数未交代，不推定神体。','speed':'宇宙航行属于交通经历，不是自身移动速度。'}});cards.append(c)
save(cards)
